	CValve::Create("mission_replay", 1, VALVE_TYPE::VTYPE_PERM);
	m_valve_nofade = CValve::Create("nofade", 0, VALVE_TYPE::VTYPE_PERM);
	InitalizeTeamValves();
	AiMaps.Reset();
	Sample_ExtractionLoc();
	CZWeapon::Open();
	LoadVehicles(m_load_ai);

	if (!m_chars_loaded)
		SignalSema(m_CharLoadSem);

