/* @socom-skeleton body OnMissionComplete__8CMissionF13MISSION_STATE */
void CMission::OnMissionComplete(MISSION_STATE state)
{
	/* 0x1f6200 (CMission::Tick's end valves): the new state is kept; single player acts
	 * only on a change, and only for an abort or while the player lives (a dead player's
	 * end comes from the death camera). With the "nofade" valve at 1 the mission ends at
	 * once (as FadeToEndMissionTick's end: _OnMissionComplete, black screen, flashes
	 * deleted, death camera reset, the exit state pushed); else the end fade starts (task
	 * MissionFadeToEnd, 1 s, then the long black flash) or, already fading, is cut to at
	 * most 1 s with no more short flashes. Was a guess (inverted alive test, nothing
	 * pushed). ELF: m_valve_nofade is not NULL-tested; the single-player branch tests
	 * the network flag a second time. */
	MISSION_STATE old = m_state;

	if (static_cast<u8>(state) != static_cast<u8>(old))
		m_state = state;

	if (theNetwork.m_bNetwork)
	{
		/* port: not written - the network round's end (0x1f6240-0x1f6450: CZBombState::
		   UninitBomb, the abort dialog dlgNetAbort.rdr after a 3 s delay, the mp_score00/08
		   and mp_winner valves, the round counter valve, CZGameState::UpdateLocalGame,
		   NetSendObjectFullUpdate, _OnMissionComplete, theGame.Push(&m_MPexitState)); the
		   port has no network play */
		return;
	}

	if (static_cast<u8>(old) == static_cast<u8>(m_state))
		return;

	if (m_state != MISSION_ABORTED && !ftsGetPlayer()->m_isAlive)
		return;

	if (m_valve_nofade->m_value == 1)
	{
		m_DelayEndMission = false;

		if (m_DelayEndMission)
			return;

		_OnMissionComplete();
		CVideo::Clear(0, 0, 0, 0);
		theHUD->m_FlashFXVector.Reset();
		theMission.m_DelayEndMission = false;
		m_FadingToEndMission = false;
		appCamera->ResetDeathCam();
		theGame.Push(&theGame.m_exitState, 0);
	}
	else if (!theNetwork.m_bNetwork)
	{
		if (!m_FadingToEndMission)
		{
			m_FadingToEndMission = true;
			theMission.m_DelayEndMission = true;
			m_fade_counter = 0;
			m_next_fade_time = 1.0f;
			zTaskScheduler.AddTask("MissionFadeToEnd", fadeToEndMissionTick, 0.98f, this);
		}
		else
		{
			if (1.0f < m_next_fade_time)
				m_next_fade_time = 1.0f;

			if (0 < m_fade_counter)
				m_fade_counter = 0;
		}
	}
#ifdef SOCOM_PORT
	SOCOM_PORT_TRACE("MISSION: complete, state %d (was %d), fading %d", (int)m_state, (int)old, (int)m_FadingToEndMission);
#endif
}

/* @socom-skeleton stub FadeToEndMissionTick__8CMissionFf */
bool CMission::FadeToEndMissionTick(float dT)
{
	/* 0x1f60a0 (task MissionFadeToEnd): count the delay down; at 0, with short flashes
	 * left (m_fade_counter > 0) a black 0.5/0.5/0.5 flash and 5 s more; at the last one
	 * (0) the long black flash (0.8 out, 5 held, 0.8 in) and 1.1 s more; after it the
	 * mission ends: _OnMissionComplete, a black screen, the flashes deleted, the death
	 * camera reset and the exit state pushed (the task ends: true). ELF quirk kept:
	 * m_DelayEndMission is cleared and then tested. */
	if (!(m_next_fade_time <= 0.0f))
	{
		m_next_fade_time -= dT;

		if (m_next_fade_time <= 0.0f)
		{
			CPnt3D black(0.0f, 0.0f, 0.0f);

			if (m_fade_counter > 0)
			{
				theHUD->Flash(0.0f, black, 0.5f, 0.5f, 0.5f);
				m_next_fade_time = 5.0f;
			}
			else if (m_fade_counter == 0)
			{
				theHUD->Flash(0.0f, black, 0.8f, 5.0f, 0.8f);
				m_next_fade_time = 1.1f;
			}
			else
			{
				m_DelayEndMission = false;

				if (m_DelayEndMission)
					return true;

#ifdef SOCOM_PORT
				SOCOM_PORT_TRACE("MISSION: faded to the end, exit state");
#endif
				_OnMissionComplete();
				CVideo::Clear(0, 0, 0, 0);
				theHUD->m_FlashFXVector.Reset();
				theMission.m_DelayEndMission = false;
				m_FadingToEndMission = false;
				appCamera->ResetDeathCam();
				theGame.Push(&theGame.m_exitState, 0);
				return true;
			}

			m_fade_counter--;
		}
	}

	return false;
}

/* @socom-skeleton stub fadeToEndMissionTick__8CMissionFfPv */
bool CMission::fadeToEndMissionTick(float dT, void *registrar)
{
	/* 0x1f6090 (task MissionFadeToEnd): tail jump, the registrar is the mission */
	return static_cast<CMission *>(registrar)->FadeToEndMissionTick(dT);
}

/* @socom-skeleton stub FadeToEndMission__8CMissionFfi */
void CMission::FadeToEndMission(float delay, int flashes)
{
	/* 0x1f5ff0 (the death camera): single player only. The first call starts the end fade
	 * (task MissionFadeToEnd at 0.98, theMission.m_DelayEndMission set) after delay
	 * seconds with that many short flashes first; later calls only shorten the delay and
	 * the flash count. */
	if (theNetwork.m_bNetwork)
		return;

	if (!m_FadingToEndMission)
	{
		m_FadingToEndMission = true;
		theMission.m_DelayEndMission = true;
		m_fade_counter = flashes;
		m_next_fade_time = delay;
		zTaskScheduler.AddTask("MissionFadeToEnd", fadeToEndMissionTick, 0.98f, this);
#ifdef SOCOM_PORT
		SOCOM_PORT_TRACE("MISSION: fade to the end in %.2f s (%d flashes)", delay, flashes);
#endif
	}
	else
	{
		if (delay < m_next_fade_time)
			m_next_fade_time = delay;

		if (flashes < m_fade_counter)
			m_fade_counter = flashes;
	}
}

/* @socom-skeleton stub CreateLadderTable__8CMissionFv */
void CMission::CreateLadderTable()
{
	/* 0x1f5c40 (Open): every ladder DI (application flags 2) of every node in the universe
	 * becomes a ladder: the node's bbox in world space (BuildMTW; min / max sorted per axis)
	 * and the DI's normal rotated to world space. A node off the grid (BuildMTW NULL) adds
	 * none of its ladders. The table is made once and kept. UNTESTED: the demo's m8 has no
	 * flag-2 DI (boot-leftovers). ELF quirk kept: the unit matrix is set twice. */
	if (zdb::NodeUniverse == NULL)
		return;

	if (m_ladders == NULL)
		m_ladders = new CLadderList();

	if (m_ladders == NULL)
		return;

	for (zdb::CNodeUniverse::iterator it = zdb::NodeUniverse->begin(); it != zdb::NodeUniverse->end(); ++it)
	{
		zdb::CNode* node = *it;

		if (node == NULL)
			continue;

		for (zdb::CDIVector::iterator di = node->m_di.begin(); di != node->m_di.end(); ++di)
		{
			zdb::CDI* poly = *di;

			if (poly->m_appflags != 2)
				continue;

			CMatrix mtw;
			sceVu0UnitMatrix(mtw.m_matrix);
			sceVu0UnitMatrix(mtw.m_matrix);

			if (node->BuildMTW(mtw) == NULL)
				break;

			CPnt3D norm(poly->m_nrm.x, poly->m_nrm.y, poly->m_nrm.z);
			CPnt3D box[2];
			mtw.Transform(&node->GetBBox()->m_min, box, 2);

			for (s32 axis = 0; axis < 3; axis++)
			{
				f32* lo = &box[0].x + axis;
				f32* hi = &box[1].x + axis;

				if (!(*lo <= *hi))
				{
					f32 t = *lo;
					*lo = *hi;
					*hi = t;
				}
			}

			mtw.Rotate(&norm, &norm, 1);

			CLadderData ladder;
			ladder.m_norm = norm;
			ladder.m_bbox.m_min = box[0];
			ladder.m_bbox.m_max = box[1];
			ladder.m_node = node;
			m_ladders->insert(m_ladders->end(), ladder);
			break; /* ELF: one ladder per node (the DI loop ends after the insert) */
		}
	}

#ifdef SOCOM_PORT
	SOCOM_PORT_TRACE("MISSION: %u ladders", (u32)m_ladders->size());
#endif
}

/* @socom-skeleton stub GetLadderByIndex__11CLadderListFi */
CLadderData * CLadderList::GetLadderByIndex(int index)
{
	/* 0x1f5bf0: a ladder id (index | LADDER_MASK); NULL past the table. UNTESTED (no m8
	 * ladders) */
	index &= ~LADDER_MASK;

	if (index < 0 || (u32)index >= size())
		return NULL;

	return &(*this)[index];
}

/* @socom-skeleton stub GetClosestLadder__11CLadderListFPC6CPnt3Df */
int CLadderList::GetClosestLadder(const CPnt3D *pos, float maxdist)
{
	/* 0x1f5a90 (ftsFixupAiMap's ladder actions): the ladder whose bottom or top is within
	 * 10 of the point's height and whose middle is the closest in x/z, nearer than maxdist;
	 * its index | LADDER_MASK, or -1. UNTESTED (no m8 ladders) */
	/* @socom-skeleton stub yThreshold$3625 */
	static f32 yThreshold = 10.0f; /* ELF: a guarded local static (init$3626) */
	s32 best = -1;
	s32 index = 0;

	for (iterator it = begin(); it != end(); ++it, index++)
	{
		const CBBox& box = it->m_bbox;

		if (!_close_enough(pos->y, box.m_min.y, yThreshold) && !_close_enough(pos->y, box.m_max.y, yThreshold))
			continue;

		CPnt3D mid;
		box.m_min.Interp(&box.m_max, 0.5f, &mid);
		CPnt3D d;
		pos->Sub(&mid, &d);
		f32 dist = sqrtf(d.x * d.x + d.z * d.z);

		if (dist < maxdist)
		{
			maxdist = dist;
			best = index;
		}
	}

	return best | LADDER_MASK;
}

/* @socom-skeleton stub aiMapPlaceItem__FPQ23zdb5CNodeRC6CPnt3DiPC6CPnt3DPC6CPnt3D */
void aiMapPlaceItem(zdb::CNode *node, const CPnt3D &pos, int axis, const CPnt3D *offset, const CPnt3D *rot)
{
	/* 0x1f5730 (ftsFixupAiMap's pickups): the node at the ground under the point
	 * (ftsGetAltitudeApprox 10 above it; the point's own height when nothing is found),
	 * turned by rot (radians, SetRotate), raised so the lowest corner of its rotated bbox
	 * along `axis` touches the ground, then moved by offset; a dynamic light node.
	 * ELF quirks kept: the lowest corner is taken along `axis` but subtracted from y; the
	 * unit matrix is set twice. */
	CPnt3D p = pos;

	if (zdb::IntersectStruct* hit = ftsGetAltitudeApprox(&p, 10.0f, false))
		p.y = hit->m_pos.y;

	CMatrix mat;
	sceVu0UnitMatrix(mat.m_matrix);
	sceVu0UnitMatrix(mat.m_matrix);

	if (rot != NULL)
		mat.SetRotate(rot);

	const CBBox* box = node->GetBBox();
	CPnt3D corners[8];

	for (s32 i = 0; i < 8; i++)
	{
		corners[i].x = (i & 1) ? box->m_max.x : box->m_min.x;
		corners[i].y = (i & 2) ? box->m_max.y : box->m_min.y;
		corners[i].z = (i & 4) ? box->m_max.z : box->m_min.z;
	}

	mat.Transform(corners, 8);
	f32 lowest = (&corners[0].x)[axis];

	for (s32 i = 1; i < 8; i++)
		lowest = std::min((&corners[i].x)[axis], lowest);

	p.y -= lowest;

	if (offset != NULL)
		p.Add(offset, &p);

	mat.m_matrix[3][0] = p.x;
	mat.m_matrix[3][1] = p.y;
	mat.m_matrix[3][2] = p.z;
	node->SetMatrix(&mat);
	node->SetDynamicLight(true, true);
}

/* @socom-skeleton stub ftsFixupAiMap__FP6CAiMap */
void ftsFixupAiMap(CAiMap *map)
{
	/* 0x1f47d0 (CMission::Open / ReOpen_Load, per AI map): the map's extra data is freed
	 * (unless 4 bytes); outside a network game the pickups listed in its reader table are
	 * placed; then every action of the map's action table is tied to its world object: the
	 * cell's centre (quantized altitude, moved 0.75 along the action's offset direction) finds
	 * a ladder (type 4: the closest within 25) or a node action (types 1, 2, 3, 5: the action
	 * of the valve named after the cell, else the closest within 25), whose id the action
	 * takes (PathFollowTick's doors, CAiSAction). */
	if (map->m_mapex_bytes != 4)
		map->FreeEx();

	/* 0x1f481c: a reader with a PICKUP block places, at its cell: WEAPON "<name>" (rot, pos:
	 * an instance of the weapon's model, a weapon pickup) and AMMO (( "<ammo>" count
	 * ["<weapon>"] ) ...: a "fiftycal_box" turned 90 degrees, an ammo pickup with those
	 * entries). Each lies on the ground under the cell (aiMapPlaceItem). Not in a network game. */
	if (!theNetwork.m_bNetwork)
	{
		for (CAiMap::readers::iterator r = map->m_readerTable.begin(); r != map->m_readerTable.end(); ++r)
		{
			_zrdr* pickup = zrdr_findtag(r->m_reader, "PICKUP");

			if (pickup == NULL)
				continue;

			CPnt3D pos = CPnt3D::zero; /* port: ELF leaves it unset for a cell off the map */
			map->GetCellPos(r->m_loc, pos);

			if (_zrdr* weapon_tag = zrdr_findtag(pickup, "WEAPON"))
			{
				CPnt3D rot = CPnt3D::zero;
				CPnt3D offset = CPnt3D::zero;
				_zrdr* first = weapon_tag->Get(0);
				char* name = first != NULL && first->type == ZRDR_STRING ? first->string : NULL;
				bool has_rot = zrdr_findPNT3D(weapon_tag, "rot", &rot);
				zrdr_findPNT3D(weapon_tag, "pos", &offset);
				rot.Scale(0.01745329f, &rot);
				CZWeapon* weapon = CZWeapon::m_listWeapons.GetWeapon(CZWeapon::GetWeaponId(name));

				if (weapon != NULL && zdb::CWorld::GetModel(weapon->GetModelName()) != NULL)
				{
					zdb::CNode* node = zdb::CNode::CreateInstance(weapon->GetModelName(), NULL, NULL);
					aiMapPlaceItem(node, pos, 1, &offset, has_rot ? &rot : NULL);
					node->m_character = 1;
					zdb::CWorld::m_world->AddTextureAssetCharacter((zdb::_RenderPhase)2, node);
					CPickup::Create(CPickup::PU_WEAPON, node, weapon);
#ifdef SOCOM_PORT
					SOCOM_PORT_TRACE("PICKUP: map %d places %s at %.1f %.1f %.1f", map->m_mapid, name, pos.x, pos.y, pos.z);
#endif
				}
			}

			_zrdr* ammo_tag = zrdr_findtag(pickup, "AMMO");

			if (ammo_tag == NULL)
				continue;

			s32 count = ammo_tag->IsArray() ? ammo_tag->array->integer - 1 : 0;

			if (count <= 0)
				continue;

			CPnt3D rot(90.0f, 0.0f, 0.0f);
			rot.Scale(0.01745329f, &rot);
			zdb::CNode* box_node = zdb::CNode::CreateInstance("fiftycal_box", NULL, NULL); /* ELF: an unset position (the matrix is set below) */

			if (box_node == NULL)
				continue;

			aiMapPlaceItem(box_node, pos, 1, NULL, &rot);
			zdb::CWorld::m_world->AddChild(box_node);
			box_node->m_character = 1;
			zdb::CWorld::m_world->AddTextureAssetCharacter((zdb::_RenderPhase)2, box_node);
			CZAmmoPickupInstance* box = new CZAmmoPickupInstance;

			for (s32 i = 0; i < count; i++)
			{
				_zrdr* entry = ammo_tag->Get(i);

				if (entry == NULL || !entry->IsArray())
					continue;

				/* ELF: the first two fields are read without a length test */
				_zrdr* ammo_name = entry->Get(0);
				_zrdr* ammo_count = entry->Get(1);
				_zrdr* weapon_name = entry->Get(2);

				if (ammo_name == NULL || ammo_count == NULL)
					continue;

				char* aname = ammo_name->type == ZRDR_STRING ? ammo_name->string : NULL;
				s32 rounds = ammo_count->GetInt();
				char* wname = weapon_name != NULL && weapon_name->type == ZRDR_STRING ? weapon_name->string : NULL;
				CZAmmo* ammo = aname != NULL ? CZAmmo::m_ammolist.GetAmmo(aname) : NULL;
				CZWeapon* item = wname != NULL ? CZWeapon::m_listWeapons.GetWeapon(wname) : NULL;

				if (ammo == NULL || rounds == 0)
					continue;

				box->m_weapons.push_back(dynamic_cast<CZFTSWeapon*>(item));
				box->m_ammo.push_back(ammo);
				box->m_counts.push_back(rounds);
			}

			CPickup::Create(CPickup::PU_AMMO, box_node, box);
#ifdef SOCOM_PORT
			SOCOM_PORT_TRACE("PICKUP: map %d places an ammo box (%u entries) at %.1f %.1f %.1f", map->m_mapid, (u32)box->m_ammo.size(), pos.x, pos.y, pos.z);
#endif
		}
	}

	for (CAiMap::actions::iterator a = map->m_actionTable.begin(); a != map->m_actionTable.end(); ++a)
	{
		const CAiMapLoc &loc = a->m_loc;

		if (!((u32)(u16)loc.y < map->m_ny && loc.x < map->m_nx))
			continue;

		CAiCell *cell = map->GetCell(loc);
		CPnt3D pos;
		pos.x = map->m_bbox.m_min.x + ((f32)loc.x * map->m_dx + 0.5f * map->m_dx);
		pos.z = map->m_bbox.m_min.z + ((f32)loc.y * map->m_dy + 0.5f * map->m_dy);

		if (cell != NULL)
			pos.y = map->m_bbox.m_min.y + ((map->m_bbox.m_max.y - map->m_bbox.m_min.y) * 0.00097656297f) * (f32)cell->m_altitude;
		else
			pos.y = 0.0f;

		if (cell->m_action) /* ELF: no NULL test (a cell on the map is never NULL) */
		{
			CAiMap::action *act = map->GetCellAction(loc);

			if (act->m_offset != 8)
			{
				CPnt3D offset;
				CAiMap::GetDirVec((CAiMap::DIR)act->m_offset, offset);
				offset.Scale(CAiMap::action::offset_length, &offset);
				pos.Add(&offset, &pos);
			}
		}

		s32 id = -1;

		switch (a->m_type)
		{
		case 1:
		case 2:
		case 3:
		case 5:
			if (cell != NULL && cell->m_name)
			{
				CAiMap::name *name = map->GetCellName(loc);
				CNodeAction *node = CNodeAction::FindActionByValve(CValve::GetByName(name->m_name));

				if (node != NULL)
					id = (u16)node->m_id;
			}

			if (id == -1)
				id = CNodeAction::GetClosestAction(&pos, 25.0f);

			break;

		case 4:
			id = theMission.m_ladders->GetClosestLadder(&pos, 25.0f); /* ELF: m_ladders not NULL-tested */
			break;

		default:
			break;
		}

		if (id != -1)
			a->m_actionId = (u16)id;
	}
}

/* @socom-skeleton body OnMissionStart__8CMissionFv */
void CMission::OnMissionStart()
{
	VALVE_STATE valveMissionState;

	m_state = MISSION_RUNNING;
	m_delay = -1.0f;
	appCamera->ResetDeathCam();
	m_DelayEndMission = false;
	m_FadingToEndMission = false;

	valveMissionState = VALVE_STATE::VSTATE_DORMANT;

	if (m_valve_complete)
	{
		valveMissionState = VALVE_STATE::VSTATE_PERMANENT;
		m_valve_complete->m_value = 0;
		m_valve_complete->MakeCallbacks(valveMissionState);
	}

	if (m_valve_failure)
	{
		valveMissionState = VALVE_STATE::VSTATE_PERMANENT;
		m_valve_failure->m_value = 0;
		m_valve_failure->MakeCallbacks(valveMissionState);
	}

	if (m_valve_abort)
	{
		valveMissionState = VALVE_STATE::VSTATE_PERMANENT;
		m_valve_abort->m_value = 0;
		m_valve_abort->MakeCallbacks(valveMissionState);
	}

	if (m_valve_timeout)
	{
		valveMissionState = VALVE_STATE::VSTATE_PERMANENT;
		m_valve_timeout->m_value = 0;
		m_valve_timeout->MakeCallbacks(valveMissionState);
	}

	if (m_valve_nofade)
	{
		valveMissionState = VALVE_STATE::VSTATE_PERMANENT;
		m_valve_nofade->m_value = 0;
		m_valve_nofade->MakeCallbacks(valveMissionState);
	}

	zdb::CWorld::m_world->m_diIntDelayCnt = 0;

	CInput::Flush();

	/* 0x1f4618: the common and mission anim sets start (their anims can be activated from
	 * now on; on-start anims run) */
	CZAnimSet* common = ZAnim.GetAnimSet("common");
	CZAnimSet* mission = ZAnim.GetAnimSet("mission");

	if (common)
		common->Start();

	if (mission)
		mission->Start();

	/* 0x1f4660: every entity hears that the mission starts (the AI seals start their script
	 * anims, CSealCtrlAi::OnMissionStart) */
	for (CEntityList::iterator it = CEntity::m_list.begin(); it != CEntity::m_list.end(); ++it)
		(*it)->OnMissionStart();

	if (!theNetwork.m_bNetwork)
		CSnd::Open();
	else
		CSnd::NetOpen();

	CSnd::m_listenerIsValid = true;
	CSndJukebox::Start();

	if (theNetwork.m_bNetwork)
	{
		// CPickup::Open(CEntity::m_list);
		theHUD->ReInit_Uninit();
		theHUD->ReInit_Init();

		if (m_pNetGame)
		{
			if (theNetwork.m_bSessionMaster)
				m_pNetGame->m_mp_major_game_state = CZNetGame::MP_MAJOR_INPLAY;

			m_pNetGame->MasterStartGame();
		}
	}
}

